WITH RECURSIVE descendants(Id, SourceImageId) AS (SELECT Id, SourceImageId FROM SceneAssetImages WHERE Id IN ('30753136591c4ca283cd163fcd00a39d','974e87e405c14760b29745d0d43799c0','05dd4f57c0ab4845ba5bb0d5b183536a') UNION ALL SELECT i.Id, i.SourceImageId FROM SceneAssetImages i JOIN descendants d ON i.SourceImageId = d.Id) SELECT Id, SourceImageId, Status, FileRelativePath, CandidateBatchId FROM SceneAssetImages WHERE Id IN (SELECT Id FROM descendants);
